internal static class WorkspaceFeedbackNativeChecks {
 static T Field<T>(ExperimentShell shell,string name){return (T)typeof(ExperimentShell).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(shell);}
 static IEnumerable<Control> Children(Control parent){foreach(Control c in parent.Controls){yield return c;foreach(var child in Children(c))yield return child;}}
 static Dictionary<string,object> Map(object value){return (Dictionary<string,object>)value;}
 static int[] Highlighted(ExperimentHub hub){return Children(hub).Where(c=>c.GetType().Name=="ObjectButton"&&(bool)c.GetType().GetField("GripHighlighted",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(c)).Select(c=>(int)c.Tag.GetType().GetField("Id",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(c.Tag)).ToArray();}
 static string Json(object value){return new JavaScriptSerializer().Serialize(value);}
 internal static async Task Grip(ExperimentShell shell,Form form,Func<Task> ready,Func<Dictionary<string,object>,Task<bool>> send,Action<bool,string> check,Action<string,Form> image){
  string hash=Convert.ToString(shell.Work["hash"]);var work=Map(shell.Work["workspace"]);string next=Json(work["next"]),draft=Json(work["draft"]);
  foreach(var command in new[]{LocalApi.D("action","bank","id","33-A"),LocalApi.D("action","capture","cells",new[]{6}),LocalApi.D("action","settings","view",LocalApi.D("local_center",1,"grip_mode","hold")),LocalApi.D("action","focus","identity",108),LocalApi.D("action","filter","expression","piece(108)")}){check(await send(command),"Accepted Grip/filter fixture "+command["action"]);await ready();}
  var local=Field<NativeCellView>(shell,"local");var hub=Field<ExperimentHub>(shell,"hub");var input=Field<ExperimentInput>(shell,"input");var windows=Field<Dictionary<string,Form>>(shell,"workWindows");var panel=Field<FlowLayoutPanel>(shell,"keyboard");windows["keyboard"].Activate();panel.Focus();input.RefreshContext();
  input.HandleKeyDown("Digit1",false,false,false,false,false);check(input.ActiveGripCell==6,"Physical Grip slot resolves canonical affecting cap C6");
  check(local.CenterCell==1&&local.GripHighlightedRegionCount==1,"C6 highlights only the included I108 sticker in actual Local C1");check(Highlighted(hub).Length>0&&Highlighted(hub).All(id=>id==108),"Only committed I108 Hub tokens intersect active C6 and the filter");image("10-grip-filter-local",windows["local"]);image("11-grip-filter-keyboard",windows["keyboard"]);
  input.HandleKeyUp("Digit1");check(local.GripHighlightedRegionCount==0&&hub.GripHighlightedObjectCount==0,"Hold release clears Local and Hub highlighting");
  check(input.SetPointerGrip(600),"Pointer explicitly selects non-affecting C600");check(local.GripHighlightedRegionCount==0&&hub.GripHighlightedObjectCount==0,"An included piece is not highlighted by a cap that cannot affect it");check(input.SetPointerGrip(6),"Pointer selects the same explicit affecting cap");var payload=Field<Dictionary<string,object>>(shell,"lastLocalCell");var unknown=Map(new JavaScriptSerializer().DeserializeObject(Json(payload)));Map(unknown["filter"])["status"]="unavailable";local.UpdateCellState(unknown);check(local.GripHighlightedRegionCount==0,"Unknown filter never appears highlighted");local.UpdateCellState(payload);check(local.GripHighlightedRegionCount==1,"Paired evaluated payload restores the exact intersection");local.SetCenter(2);check(local.GripHighlightedRegionCount==0,"Changing Local center clears highlight while awaiting its paired payload");local.SetCenter(1);
  check(await send(LocalApi.D("action","filter","expression","piece(109)")),"Accepted excluded-piece filter");await ready();windows["keyboard"].Activate();panel.Focus();check(input.SetPointerGrip(6),"Grip explicitly reacquired after filter change");check(!local.GripHighlightsRegion(108)&&local.GripHighlightedRegionCount==1,"Filter excludes I108 but retains the separate matching I109 region affected by C6");check(hub.GripHighlightedObjectCount==0,"Excluded Current I108 is not highlighted in Hub");check(await send(LocalApi.D("action","filter","expression","nothing")),"Accepted empty filter");await ready();windows["keyboard"].Activate();panel.Focus();check(input.SetPointerGrip(6),"Grip selected under empty filter");check(local.GripHighlightedRegionCount==0&&hub.GripHighlightedObjectCount==0,"Empty filter leaves no Grip highlights");input.Reset("Fixture complete");
  check(Convert.ToString(shell.Work["hash"])==hash&&Json(Map(shell.Work["workspace"])["next"])==next&&Json(Map(shell.Work["workspace"])["draft"])==draft,"Grip/filter inspection preserves every label, locked Next and draft");
  foreach(var command in new[]{LocalApi.D("action","filter","expression","all"),LocalApi.D("action","focus","identity",35778),LocalApi.D("action","settings","view",LocalApi.D("local_center",55)),LocalApi.D("action","capture","cells",new[]{55})}){check(await send(command),"Restored Grip fixture "+command["action"]);await ready();}
 }
 internal static async Task Help(ExperimentShell shell,Form form,Func<Task> ready,Action<bool,string> check,Action<string,Form> image){
  string hash=Convert.ToString(shell.Work["hash"]),context=Json(shell.Work["workspace"]);var keyboard=Field<FlowLayoutPanel>(shell,"keyboard");Field<Dictionary<string,Form>>(shell,"workWindows")["keyboard"].Activate();keyboard.Focus();
  form.BeginInvoke((Action)delegate{typeof(ExperimentShell).GetMethod("RunCommand",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(shell,new object[]{"help"});});Form dialog=null;var deadline=DateTime.UtcNow.AddSeconds(20);while(dialog==null){dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f.Visible&&f.Text=="Help · Magic 600 Cell");if(DateTime.UtcNow>deadline)throw new TimeoutException("Help did not open");await Task.Delay(40);}
  var search=Children(dialog).OfType<TextBox>().Single(c=>c.AccessibleName=="Search help topics or feature descriptions");var topics=Children(dialog).OfType<ListBox>().Single();var article=Children(dialog).OfType<RichTextBox>().Single();check(search.Focused&&article.ReadOnly,"Help owns text input and its article is read-only");var titles=topics.Items.Cast<object>().Select(item=>item.ToString()).ToArray();check(new[]{"Workspace","Blocks & goals","Grip & Twist","Keyboard","Macro Base","Operation","Protection","Local & Global","Work sheets","Session & recovery","Residuals, buffers and repeated work"}.All(titles.Contains),"Help retains every feature introduction and integrated residual guidance");search.Text="no-topic-404";check(topics.Items.Count==0&&search.Text=="no-topic-404"&&article.Text.Contains("No matching topics"),"Empty Help results preserve the input and explain recovery");search.Text="Grip";check(topics.Items.Count>0,"Help searches actual feature descriptions");search.Clear();dialog.Size=dialog.MinimumSize;await Task.Delay(150);
  foreach(var readout in Children(dialog).OfType<Label>().Where(c=>c.Parent.GetType().Name=="WorkReadout")){check(readout.GetPreferredSize(new Size(readout.ClientSize.Width,0)).Height<=readout.ClientSize.Height+2,"Help minimum-width identity/protection text fits: "+readout.Text.Split('\n')[0]);}
  image("12-help-compact",dialog);((IButtonControl)dialog.CancelButton).PerformClick();await ready();check(dialog.IsDisposed&&!Field<bool>(shell,"modal"),"Help cancel closes its modal input boundary");check(hash==Convert.ToString(shell.Work["hash"]),"Help preserves full model state");
  var now=Map(shell.Work["workspace"]);var before=Map(new JavaScriptSerializer().DeserializeObject(context));foreach(string key in new[]{"current","next","draft","bank","roles","prefix"})if(before.ContainsKey(key))check(Json(before[key])==Json(now[key]),"Help preserves "+key);check(keyboard.ContainsFocus,"Help restores the keyboard tool focus");
 }
}
